<?php

namespace App\Filament\Resources\Invoices\Pages;

use App\Filament\Resources\Invoices\InvoiceResource;
use App\Services\OFSService;
use Filament\Actions\Action;
use Filament\Actions\EditAction;
use Filament\Infolists\Components\TextEntry;
use Filament\Notifications\Notification;
use Filament\Resources\Pages\ViewRecord;
use Filament\Schemas\Components\Section;
use Filament\Support\Enums\Width;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\HtmlString;

class ViewInvoice extends ViewRecord
{
    protected static string $resource = InvoiceResource::class;

    public function getHeaderActions(): array
    {
        return [
            EditAction::make(),

            Action::make('showFiscal')
                ->label('Fiscal Invoice')
                ->icon('heroicon-o-receipt-refund')
                ->modalHeading('Fiscal Invoice')
                ->modalWidth(Width::ScreenSmall)
                ->modalSubmitAction(false)
                ->modalCancelActionLabel('Close')
                ->modalContent(function ($record) {
                    $base64 = $record->fiscal_meta['invoiceImagePngBase64'] ?? null;

                    if (!$base64) {
                        return new HtmlString('<p>No invoice image available</p>');
                    }

                    return new HtmlString(
                        '<div style="text-align: center;">' .
                        '<img src="data:image/png;base64,' . $base64 . '" alt="Fiscal Invoice" style="max-width:100%; height:auto;" />' .
                        '</div>'
                    );
                }),

            // TEST ACTIONS - For debugging OFS API connectivity
            Action::make('test_attention')
                ->label('Test API (/api/attention)')
                ->color('info')
                ->action(function () {
                    try {
                        $ofs = new OFSService();
                        $response = $ofs->testAttention();

                        logger('OFS Attention Response:', [
                            'status' => $response->status(),
                            'body' => $response->body(),
                            'json' => $response->json(),
                        ]);

                        if ($response->successful()) {
                            Notification::make()
                                ->title('✅ API dostupan!')
                                ->body('Status: ' . $response->status() . ' - OFS ESIR API je dostupan i pravilno konfigurisan.')
                                ->success()
                                ->send();
                        } else {
                            Notification::make()
                                ->title('❌ API nije dostupan')
                                ->body('Status: ' . $response->status() . "\n" . $response->body())
                                ->danger()
                                ->send();
                        }
                    } catch (\Exception $e) {
                        Notification::make()
                            ->title('❌ Greška')
                            ->body($e->getMessage())
                            ->danger()
                            ->send();
                    }
                }),

            Action::make('test_settings')
                ->label('Test Settings (/api/settings)')
                ->color('info')
                ->action(function () {
                    try {
                        $ofs = new OFSService();
                        $response = $ofs->getSettings();

                        if ($response->successful()) {
                            $data = $response->json();

                            logger('OFS Settings:', $data);
                            Notification::make()
                                ->title('Settings uspješno učitani!')
                                ->body('Printer: ' . ($data['printerName'] ?? 'N/A') . "\nLPFR URL: " . ($data['lpfrUrl'] ?? 'N/A'))
                                ->success()
                                ->send();
                        } else {
                            Notification::make()
                                ->title('❌ Greška pri učitavanju settings-a')
                                ->body('Status: ' . $response->status() . "\n" . $response->body())
                                ->danger()
                                ->send();
                        }
                    } catch (\Exception $e) {
                        Notification::make()
                            ->title('❌ Greška')
                            ->body($e->getMessage())
                            ->danger()
                            ->send();
                    }
                }),

            // MAIN FISCALIZATION ACTION
            Action::make('fiskalizuj_i_stampa')
                ->label('Fiskalizuj i štampaj')
                ->icon('heroicon-o-printer')
                ->color('success')
                ->action(function ($record) {
                    try {
                        $ofs = new OFSService();

                        Log::info('Starting fiscalization for invoice', [
                            'invoice_id' => $record->id,
                            'invoice_number' => $record->id,
                            'client_id' => $record->client_id,
                        ]);

                        // Build invoice items array
                        $items = [];
                        $totalAmount = 0;
                        foreach ($record->items as $item) {
                            $itemUnitPrice = (float) ($item->unit_price / 100); // Convert to KM
                            $itemQuantity = (float) $item->quantity;
                            $itemTotal = $itemUnitPrice * $itemQuantity;
                            $totalAmount += $itemTotal;
                            $taxCategory = $item->article->tax_category;

                            $items[] = [
                                'name' => $item->name . ' / ' . $item->article->unit,
                                'quantity' => $itemQuantity,
                                'unitPrice' => $itemUnitPrice,
                                'totalAmount' => $itemTotal, // REQUIRED by API
                                'labels' => [$taxCategory], // HARDCODED: Tax category (A = nije u PDV, Đ = O-PDV 20%, E = P-PDV 10%, G = Bez PDV)
                                // Optional fields:
                                // 'gtin' => '', // Barcode
                                // 'unitOfMeasure' => 'kom',
                            ];
                        }

                        Log::info('Built invoice items', [
                            'items' => $items,
                            'total_amount' => $totalAmount,
                        ]);

                        // Build the OFS ESIR API payload - MUST be wrapped in "invoiceRequest"
                        $payload = [
                            //"renderReceiptImage": true,
                            //                "receiptImageFormat": "Png",
                            //                "receiptLayout": "Slip",
                            'renderReceiptImage' => true,
                            'receiptImageFormat' => 'Png',
                            'receiptLayout' => 'Slip',
                            'receiptHeaderImage' => '',
                            'receiptFooterImage' => '',
                            'receiptHeaderTextLines' => ['receiptHeaderTextLines 123', 'receiptHeaderTextLines 456'],
                            'receiptFooterTextLines' => ['receiptFooterTextLines 123', 'receiptFooterTextLines 456'],
                            'buyerId' => null, // Default to null, may be overridden for wholesale below



                            'invoiceRequest' => [
                                // REQUIRED: Invoice type
                                'invoiceType' => 'Normal', // Normal, Proforma, Copy, Training

                                // REQUIRED: Transaction type
                                'transactionType' => 'Sale', // Sale or Refund

                                // REQUIRED: Payment info
                                'payment' => [
                                    [
                                        'amount' => $totalAmount,
                                        'paymentType' => 'WireTransfer', // HARDCODED: Cash, Card, Check, WireTransfer, Voucher, MobileMoney, Other
                                    ],
                                ],

                                // REQUIRED: Invoice items
                                'items' => $items,

                                // Optional: Cashier name
                                'cashier' => auth()->user()?->getFilamentName() ?? 'System',

                                // Optional: Buyer ID (for B2B/wholesale)
                                // 'buyerId' => '111758195', // JIB kupca or 'VP:' prefix for veleprodaja
                                // 'buyerCostCenterId' => '', // Optional cost center
                            ],
                        ];

                        // If wholesale transaction, add buyer ID with VP: prefix
                        if (isset($record->is_wholesale) && $record->is_wholesale && isset($record->client->jib)) {

                            if ($record->client->country !== 'BIH') {
                                Log::warning('Wholesale transaction but client is not from BIH', [
                                    'client_id' => $record->client_id,
                                    'client_country' => $record->client->country,
                                ]);

                                $payload['invoiceRequest']['buyerId'] = 'VP:9999999999999';

                            } else {
                                $payload['invoiceRequest']['buyerId'] = 'VP:' . $record->client->jib;
                            }


                        }

                        Log::info('Final invoice payload', [
                            'payload' => $payload,
                            'payload_json' => json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE),
                        ]);

                        // Send to OFS API
                        $response = $ofs->createInvoice($payload);

                        logger('OFS Create Invoice Response:', [
                            'status' => $response->status(),
                            'body' => $response->body(),
                            'json' => $response->json(),
                        ]);

                        if ($response->successful()) {
                            $data = $response->json();

                            Log::info('Fiscalization successful', ['response_data' => $data]);

                            // Save fiscal data to database
                            $record->update([
                                'is_fiscalized' => true,
                                'fiscal_invoice_number' => $data['invoiceNumber'] ?? null,
                                'fiscal_counter' => $data['invoiceCounter'] ?? null,
                                'fiscal_verification_url' => $data['verificationUrl'] ?? null,
                                'fiscalized_at' => now(),
                                'fiscal_meta' => $data, // Complete response for audit/reprint
                            ]);

                            Notification::make()
                                ->title('✅ Račun uspješno fiskalizovan!')
                                ->body(
                                    'Fiskalni broj: ' . ($data['invoiceNumber'] ?? 'N/A') . "\n" .
                                    'Brojač: ' . ($data['invoiceCounter'] ?? 'N/A') . "\n" .
                                    'Ukupno: ' . number_format($totalAmount, 2, ',', '.') . ' KM'
                                )
                                ->success()
                                ->send();
                        } else {
                            Log::error('Fiscalization failed', [
                                'status' => $response->status(),
                                'body' => $response->body(),
                                'json' => $response->json(),
                            ]);

                            Notification::make()
                                ->title('Greška prilikom fiskalizacije')
                                ->body('Status: ' . $response->status() . "\n" . $response->body())
                                ->danger()
                                ->send();
                        }
                    } catch (\Exception $e) {
                        Log::error('Exception during fiscalization', [
                            'message' => $e->getMessage(),
                            'trace' => $e->getTraceAsString(),
                        ]);

                        Notification::make()
                            ->title('Greška!')
                            ->body('Exception: ' . $e->getMessage())
                            ->danger()
                            ->send();
                    }
                })
                ->requiresConfirmation()
                ->modalHeading('Potvrda fiskalizacije')
                ->modalDescription('Da li ste sigurni da želite fiskalizovati i odštampati račun?'),
        ];
    }
}
